INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Lichtwellenleiter immer teurer als Kupferkabel sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Kosten variieren je nach Einsatz"}, {"text": "Ja", "correct": false, "because": "Nicht zwangsläufig teurer"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich, wenn ich Lichtwellenleiter für ein IT-Netzwerk auswähle?', 3, '[{"text": "Übertragungsgeschwindigkeit", "correct": true, "because": "Entscheidend für Performance"}, {"text": "Farbe", "correct": false, "because": "Irrelevant"}, {"text": "Gewicht", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale machen Lichtwellenleiter in der IT nützlich?', 5, '[{"text": "Hohe Bandbreite", "correct": true, "because": "Ermöglicht schnelle Datenübertragung"}, {"text": "Störunanfälligkeit", "correct": true, "because": "Resistent gegen elektromagnetische Störungen"}, {"text": "Hohe Latenz", "correct": false, "because": "Nachteil"}, {"text": "Schwere Bauweise", "correct": false, "because": "Leicht und flexibel"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Lichtwellenleiter nutzen Licht zur Datenübertragung. b) Sie sind immer langsamer als Kupferkabel.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Schneller als Kupfer"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich Lichtwellenleiter für ein Netzwerk plane?', 4, '[{"text": "Übertragungsreichweite", "correct": false, "because": "Wichtig für Planung"}, {"text": "Bandbreite", "correct": false, "because": "Entscheidend für Leistung"}, {"text": "Kabeldesign", "correct": true, "because": "Ästhetisch, nicht technisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Lichtwellenleiter elektromagnetische Störungen beeinflussen?', 2, '[{"text": "Nein", "correct": true, "because": "Unempfindlich gegen Störungen"}, {"text": "Ja", "correct": false, "because": "Glasfaser ist störresistent"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich, wenn ich Lichtwellenleiter in einem IT-Netzwerk einsetze?', 3, '[{"text": "Hohe Datenraten", "correct": true, "because": "Verbessert Performance"}, {"text": "Geringere Kosten", "correct": false, "because": "Nicht primär"}, {"text": "Schwere Verkabelung", "correct": false, "because": "Nicht Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften sind bei Lichtwellenleitern für IT-Netzwerke entscheidend?', 5, '[{"text": "Geringe Dämpfung", "correct": true, "because": "Ermöglicht lange Strecken"}, {"text": "Hohe Bandbreite", "correct": true, "because": "Schnelle Übertragung"}, {"text": "Hohe Latenz", "correct": false, "because": "Nachteil"}, {"text": "Schwere Struktur", "correct": false, "because": "Leichtbauweise"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Lichtwellenleiter sind schneller als Kupferkabel. b) Sie sind immer zerbrechlicher. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Robust mit Schutz"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, wenn ich Lichtwellenleiter für ein Netzwerk auswähle?', 4, '[{"text": "Spleißtechnik", "correct": false, "because": "Wichtig für Verbindung"}, {"text": "Übertragungsrate", "correct": false, "because": "Entscheidend für Leistung"}, {"text": "Kabeldekoration", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind Lichtwellenleiter immer teurer als Kupferkabel?', 2, '[{"text": "Nein", "correct": true, "because": "Kosten abhängig von Einsatz"}, {"text": "Ja", "correct": false, "because": "Nicht zwangsläufig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bieten Lichtwellenleiter in der IT?', 4, '[{"text": "Hohe Geschwindigkeit", "correct": true, "because": "Schnelle Datenübertragung"}, {"text": "Störresistenz", "correct": true, "because": "Keine elektromagnetischen Einflüsse"}, {"text": "Hohe Latenz", "correct": false, "because": "Nachteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Lichtwellenleiter keine Energie übertragen können. Stimmt das?', 2, '[{"text": "Ja", "correct": true, "because": "Nur Datenübertragung"}, {"text": "Nein", "correct": false, "because": "Keine Stromübertragung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was wähle ich, um Lichtwellenleiter für ein großes Netzwerk auszuwählen?', 3, '[{"text": "Reichweite", "correct": true, "because": "Wichtig für Entfernung"}, {"text": "Kabelgewicht", "correct": false, "because": "Sekundär"}, {"text": "Farbcodierung", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Lichtwellenleiter haben geringe Dämpfung. b) Sie sind anfälliger für Störungen als Kupfer.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Störresistent"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren berücksichtige ich bei Lichtwellenleitern für IT?', 5, '[{"text": "Bandbreitenkapazität", "correct": true, "because": "Schnelle Übertragung"}, {"text": "Installationskosten", "correct": true, "because": "Beeinflusst Budget"}, {"text": "Kabeldesign", "correct": false, "because": "Ästhetisch"}, {"text": "Bürogröße", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist unwichtig, wenn ich Lichtwellenleiter für ein Netzwerk plane?', 3, '[{"text": "Signalreichweite", "correct": false, "because": "Wichtig für Planung"}, {"text": "Dämpfungswerte", "correct": false, "because": "Beeinflusst Leistung"}, {"text": "Kabelverpackung", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind Lichtwellenleiter für kurze Distanzen ungeeignet?', 3, '[{"text": "Nein", "correct": true, "because": "Auch für kurze Strecken nutzbar"}, {"text": "Ja", "correct": false, "because": "Flexibel einsetzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Lichtwellenleiter für Echtzeitanwendungen geeignet sind?', 2, '[{"text": "Ja", "correct": true, "because": "Hohe Geschwindigkeit"}, {"text": "Nein", "correct": false, "because": "Ideal für Echtzeit"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Feature ist entscheidend, wenn ich Lichtwellenleiter für IT-Netzwerke nutze?', 4, '[{"text": "Hohe Datenrate", "correct": true, "because": "Sichert Performance"}, {"text": "Schwere Bauweise", "correct": false, "because": "Nicht erwünscht"}, {"text": "Farbliche Gestaltung", "correct": false, "because": "Irrelevant"}]');
